"""Gera slides HTML autocontidos a partir dos resultados REAIS do treinamento."""
from pathlib import Path
from html import escape
import json

DIR=Path(__file__).resolve().parent
META=DIR/'artefatos'/'metricas.json'

def pt(n,casas=0): return f'{n:,.{casas}f}'.replace(',','_').replace('.',',').replace('_','.')
def card(t,body):return f'<section class="slide"><div class="top">FLUXOIA <span>SENAC UC9 · GRUPO 6</span></div><h1>{t}</h1>{body}<div class="foot">Metro Interstate Traffic Volume · UCI · 2012–2018</div></section>'

def gerar():
    m=json.loads(META.read_text(encoding='utf-8'))
    nome=m['selecionado'];res=m['resultados'][nome]['teste'];base=m['resultados']['Baseline por dia/hora']['teste']
    linhas=''.join(f'<tr><td>{escape(nome_)}</td><td>{pt(item["validacao"]["mae"],1)}</td><td>{pt(item["teste"]["mae"],1)}</td><td>{pt(item["teste"]["r2"],3)}</td></tr>' for nome_,item in m['resultados'].items())
    imp=''.join(f'<li><strong>{escape(d["variavel"])}</strong> — aumento do MAE: {pt(d["aumento_mae"],1)} veículos</li>' for d in m['importancia_permutacao'][:5])
    viés=''.join(f'<li>{escape(d["grupo"])}: MAE de {pt(d["mae"],1)} veículos (n={d["n"]})</li>' for d in m['comparacao_grupos']['periodo'])
    slides=[
      card('Previsão inteligente do volume de trânsito','<p class="lead">Como estimar o número de veículos por hora para apoiar o planejamento de manutenção de vias?</p><div class="pill">Regressão · Séries temporais · Dados reais</div><p class="fine">Local analisado: I-94 sentido oeste, entre Minneapolis e St. Paul, EUA. Não são dados de Cuiabá.</p>'),
      card('O problema real','<p class="lead">Intervenções em vias com tráfego elevado podem expor mais veículos a transtornos.</p><ul><li><b>Quem se beneficia:</b> equipes responsáveis pelo planejamento viário.</li><li><b>O que o sistema prevê:</b> volume horário de veículos.</li><li><b>Qual decisão ajuda:</b> avaliar horários potencialmente menos movimentados.</li></ul><p class="fine">Volume elevado não prova congestionamento ou lentidão.</p>'),
      card('Dados e preparação',f'<div class="triple"><div><b>{pt(m["origem_linhas"])}</b><span>registros originais</span></div><div><b>{pt(m["horas_unicas"])}</b><span>horários únicos</span></div><div><b>8</b><span>variáveis na fonte</span></div></div><p>Fonte: UCI Machine Learning Repository, John Hogue (2019), licença CC BY 4.0.</p><ul><li>Registros horários de 2012 a 2018.</li><li>Consolidação de horas repetidas e tratamento de datas.</li><li>Variáveis de calendário conhecidas antes do horário previsto.</li></ul>'),
      card('Modelagem e validação',f'<p class="lead">Divisão cronológica sem embaralhar dados.</p><div class="triple"><div><b>{pt(m["treino_n"])}</b><span>treino</span></div><div><b>{pt(m["validacao_n"])}</b><span>validação</span></div><div><b>{pt(m["teste_n"])}</b><span>teste</span></div></div><ul><li>Baseline: média por hora e dia da semana.</li><li>Regressão Ridge, Árvore de Decisão e Random Forest.</li><li>Ajuste de profundidade da árvore e seleção por MAE de validação.</li></ul>'),
      card('Resultados dos algoritmos',f'<table><thead><tr><th>Modelo</th><th>MAE validação</th><th>MAE teste</th><th>R² teste</th></tr></thead><tbody>{linhas}</tbody></table><p class="lead">Modelo selecionado: <strong>{escape(nome)}</strong>.</p><p>MAE em teste: <strong>{pt(res["mae"],1)}</strong> veículos; baseline: <strong>{pt(base["mae"],1)}</strong> veículos.</p><p class="fine">São números calculados em registros históricos posteriores ao treinamento. Menor MAE significa menor erro médio.</p>'),
      card('Explicabilidade e análise crítica',f'<div class="cols"><div><h2>Variáveis relevantes</h2><ul>{imp}</ul></div><div><h2>Erros por período</h2><ul>{viés}</ul></div></div><p class="fine">Importância por permutação não demonstra causalidade. Variações por período não equivalem a viés demográfico.</p>'),
      card('Simulação de impacto e demonstração',f'<p class="lead">Podemos comparar a exposição hipotética de veículos em uma intervenção às 16h com a exposição em um horário escolhido pelo modelo.</p><ul><li>Seleção de horários feita pela previsão.</li><li>Comparação com volumes realmente observados no conjunto de teste.</li><li>Custo por veículo é uma premissa editável, não uma economia comprovada.</li></ul><div class="pill">DEMONSTRAÇÃO: abrir app.py no Streamlit</div>'),
      card('Conclusão e próximos passos','<p class="lead">O FluxoIA transforma dados históricos em estimativas que podem apoiar o planejamento de intervenções viárias.</p><ul><li>O modelo não prevê acidentes, filas nem tempo de viagem.</li><li>Os dados são de uma rodovia nos EUA, não de Cuiabá.</li><li>Para uso na região, precisaríamos de contagens locais e nova validação.</li></ul><p><b>Fonte:</b> Hogue, J. (2019), UCI, DOI 10.24432/C5X60B.</p>')
    ]
    html='''<!doctype html><html lang="pt-br"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FluxoIA — Apresentação UC9</title><style>
*{box-sizing:border-box}body{margin:0;font-family:Arial,system-ui,sans-serif;background:#161e34;color:#17233f}section.slide{display:none;background:#f8f9fd;width:min(1100px,94vw);height:min(650px,88vh);margin:5vh auto;padding:45px 55px;border-radius:21px;box-shadow:0 25px 70px #0005;overflow:auto}section.slide.active{display:block}.top{display:flex;justify-content:space-between;color:#7384a8;font-size:14px;font-weight:800;letter-spacing:.09em}.top span{font-size:12px}h1{font-size:40px;margin:36px 0 27px;letter-spacing:-1.2px;color:#142747;max-width:850px}h2{font-size:22px;color:#1f3c6b}p,li{font-size:20px;line-height:1.5}li{margin:10px 0}.lead{font-size:27px;color:#354d7c}.fine{font-size:15px;color:#78839e}.triple{display:flex;gap:14px}.triple div{flex:1;background:#e9edff;border-radius:15px;padding:20px}.triple b{display:block;font-size:29px;color:#3b4bad}.triple span{font-size:14px}.pill{display:inline-block;background:#d9ebf6;color:#235978;border-radius:10px;padding:12px 18px;font-weight:bold}.foot{margin-top:40px;font-size:13px;color:#8a97ad}.cols{display:flex;gap:40px}.cols>div{width:50%}.cols li{font-size:16px}table{border-collapse:collapse;width:100%;font-size:17px}td,th{padding:15px;text-align:left;border-bottom:1px solid #dde3ed}th{background:#e5edff}.nav{position:fixed;bottom:12px;left:50%;transform:translateX(-50%);color:#e7ebf2;font-size:14px}.nav button{border:0;background:#536bca;color:white;border-radius:8px;padding:10px 18px;font-weight:bold;cursor:pointer;margin:0 8px}@media(max-width:720px){h1{font-size:28px}.slide{padding:24px!important}.triple{flex-wrap:wrap}.lead{font-size:20px}.cols{flex-wrap:wrap}.cols>div{width:100%}}</style>
'''+''.join(slides)+'''<div class="nav"><button onclick="show(-1)">◀ Anterior</button><span id="num"></span><button onclick="show(1)">Próximo ▶</button></div><script>let n=0;const s=[...document.querySelectorAll('section.slide')];function render(){s.forEach((x,i)=>x.classList.toggle('active',i===n));document.getElementById('num').textContent=(n+1)+' / '+s.length;}function show(d){n=(n+d+s.length)%s.length;render();}document.addEventListener('keydown',e=>{if(['ArrowRight','PageDown',' '].includes(e.key))show(1);if(['ArrowLeft','PageUp'].includes(e.key))show(-1);});render();</script></html>'''
    out=DIR/'APRESENTACAO_OFFLINE.html';out.write_text(html,encoding='utf-8')
    print('Apresentação criada:',out)
    return out

if __name__=='__main__':gerar()
